<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import { amountInput, yuanInput, lineKinds, artistServiceKinds, isSpecification, type SpecData, type Specification } from '@/api/modules/trade'
import { validSupplyId } from '@/api/modules/supply'
const props=defineProps<{disabled:boolean;previous?:string}>(),emit=defineEmits<{submit:[body:Omit<SpecData,'review'>&{previous_spec_id:string|null}]}>()
const f=reactive({title:'',provider:'',kind:'',price:'',tier:'',version:'',sample:'',final:'',revisions:'',deliverables:'',terms:'',previous:props.previous||'',serviceKind:'',rule:'',source:'',retry:'',months:'',halo:'',deliveryVersion:'',deliverySource:'',acceptance:'',cancellation:''})
const custom=computed(()=>['PRIVATE_CUSTOMIZATION','MANUAL_SAMPLE'].includes(f.serviceKind))
watch(custom,v=>{if(v)f.kind='PRODUCTION'})
const artist=computed(()=>Object.hasOwn(artistServiceKinds,f.serviceKind))
const body=computed(()=>{
 const unit=artist.value?yuanInput(f.price):amountInput(f.price),deliverables=f.deliverables.split('\n').map(s=>s.trim()).filter(Boolean)
 const shared={version:f.version.trim(),service_tier:f.tier.trim(),deliverables,terms:f.terms.trim()}
 let specification:unknown
 if(artist.value)specification={...shared,service:{kind:f.serviceKind,unit:f.serviceKind==='AVATAR_CREATION'?'PERSON_FIRST':f.serviceKind==='AVATAR_HOSTING'?'AVATAR_MONTH':'HALO_APPLICATION',rule_version:f.rule.trim(),source_ref:f.source.trim(),retry_limit:f.serviceKind==='AVATAR_CREATION'?amountInput(f.retry,0,100):0,hosting_months:f.serviceKind==='AVATAR_HOSTING'?amountInput(f.months,1,120):null,halo_level:f.serviceKind==='HALO_REVIEW'?amountInput(f.halo,2,2):null,failure_policy:'REFUND_UNDELIVERED'}}
 else specification={...shared,sample_seconds:amountInput(f.sample,0,100000),final_seconds:amountInput(f.final,0,100000),revision_limit:amountInput(f.revisions,0,100000),...custom.value?{customization_delivery:{version:f.deliveryVersion.trim(),source_ref:f.deliverySource.trim(),preview_payment_order:'PREVIEW_BEFORE_INTERIM',acceptance_hours:amountInput(f.acceptance,1,720),cancellation_terms:f.cancellation.trim()}}:{}}
 if(!f.title.trim()||!validSupplyId(f.provider)||!artist.value&&!Object.hasOwn(lineKinds,f.kind)||unit===null||!isSpecification(specification)||new Set(deliverables).size!==deliverables.length||f.previous&&!validSupplyId(f.previous))return null
 return {title:f.title.trim(),provider_party_id:f.provider,line_kind:artist.value?'OTHER' as const:custom.value?'PRODUCTION' as const:f.kind as keyof typeof lineKinds,unit_minor:unit,currency:'CNY' as const,specification:specification as Specification,previous_spec_id:f.previous||null,...artist.value||custom.value?{product_profile:{version:'V5' as const,type:f.serviceKind as keyof typeof artistServiceKinds|'PRIVATE_CUSTOMIZATION'|'MANUAL_SAMPLE'}}:{}}
})
</script>
<template><form class="trade-form" @submit.prevent="body && emit('submit',body)"><fieldset :disabled="disabled">
 <section class="supply-card"><h2>服务对象</h2><label>商品类别<select v-model="f.serviceKind" data-testid="trade-spec-service-kind"><option value="">影视制作与许可（既有业务）</option><option value="PRIVATE_CUSTOMIZATION">V5 私人定制</option><option value="MANUAL_SAMPLE">V5 人工样片</option><option v-for="(label,key) in artistServiceKinds" :key="key" :value="key">{{label}}</option></select></label><p v-if="artist" class="muted">只填写该服务的实际约定。认证费不保证通过；档案交付与长期模型训练分别核对。</p></section>
 <section class="supply-card"><h2>商品信息</h2><div class="trade-fields two"><label>商品名称 *<input v-model="f.title" maxlength="200" required placeholder="待填写"></label><label>实际提供方主体编号 *<input v-model="f.provider" required placeholder="完整主体编号"></label></div></section>
 <section class="supply-card"><h2>服务与计价</h2><div class="trade-fields four"><label v-if="!artist">服务明细类型 *<select v-model="f.kind" :disabled="custom" required><option value="">待选择</option><option v-for="(name,key) in lineKinds" :key="key" :value="key">{{name}}</option></select></label><label>{{artist?'服务单价（元） *':'服务单价（人民币分） *'}}<input v-model="f.price" :inputmode="artist?'decimal':'numeric'" required :placeholder="artist?'明确费用，最多两位小数':'整数分'"></label><label>币种<input value="人民币 CNY" disabled></label><label>服务档位 *<input v-model="f.tier" maxlength="100" required placeholder="待填写"></label></div></section>
 <section class="supply-card"><h2>规格参数</h2><div class="trade-fields four"><label>规格版本 *<input v-model="f.version" maxlength="128" required placeholder="待填写"></label><template v-if="!artist"><label>样片时长（秒） *<input v-model="f.sample" inputmode="numeric" required placeholder="明确填写，含 0"></label><label>成片时长（秒） *<input v-model="f.final" inputmode="numeric" required placeholder="明确填写，含 0"></label><label>可修改次数 *<input v-model="f.revisions" inputmode="numeric" required placeholder="明确填写，含 0"></label></template><template v-else><label>服务规则版本 *<input v-model="f.rule" maxlength="128" required></label><label>规则来源 *<input v-model="f.source" maxlength="128" required></label><label v-if="f.serviceKind==='AVATAR_CREATION'">约定重试次数 *<input v-model="f.retry" inputmode="numeric" required placeholder="0—100，按实际约定"></label><label v-if="f.serviceKind==='AVATAR_HOSTING'">约定托管月数 *<input v-model="f.months" inputmode="numeric" required placeholder="1—120，按实际约定"></label><label v-if="f.serviceKind==='HALO_REVIEW'">审核等级 *<select v-model="f.halo" required><option value="">待选择</option><option value="2">L2认证审核</option><option disabled>L3本轮不可购买</option></select></label></template></div><p v-if="artist" class="muted">未交付部分按原订单办理退款；首次核实收款后起算，续期接已有期限，实际日期以服务记录为准，续期提醒不是自动扣款。</p></section>
 <section v-if="custom" class="supply-card" data-testid="trade-spec-delivery"><h2>定制履约约定</h2><div class="trade-fields two"><label>履约规则版本 *<input v-model="f.deliveryVersion" maxlength="128" required></label><label>原约定来源 *<input v-model="f.deliverySource" maxlength="128" required></label><label>明确收讫后确认期限（小时） *<input v-model="f.acceptance" inputmode="numeric" required placeholder="1—720，按实际约定"></label><label>取消、保留金额与退款约定 *<textarea v-model="f.cancellation" maxlength="8000" required></textarea></label></div><p class="muted">先提供正式预览，再办理原约定中间付款条件。{{f.serviceKind==='MANUAL_SAMPLE'?'人工样片采用自身两期约定。':'私人定制采用原订单三期约定。'}}规则、费用和取消条款独立审核后保存，新规格不改写历史订单。</p></section>
 <section class="supply-card"><h2>交付与条款</h2><div class="trade-fields two"><label>约定交付内容 *<textarea v-model="f.deliverables" required placeholder="每行一项，最多 30 项"></textarea></label><label>完整条款 *<textarea v-model="f.terms" maxlength="8000" required placeholder="待填写"></textarea></label></div></section>
 <section class="supply-card"><h2>历史版本关联</h2><label class="trade-inline">上一商品版本<input v-model="f.previous" placeholder="首次创建留空；新版本填写原记录编号"></label><p class="muted">新版本独立审核；价格、规格和条款不会改写历史订单。</p></section>
 <div class="trade-footer"><RouterLink to="/trade/specifications" class="button-link outline">返回商品</RouterLink><button class="primary" :disabled="disabled || !body">提交规格审核</button></div>
 </fieldset></form></template>
